def safe_int(value, default=0):
    try:
        return int(value)
    except (ValueError, TypeError):
        return default

def safe_divide(a, b):
    if b == 0:
        return None
    return a / b

def parse_positive_int(value):
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        return None
    if parsed <= 0:
        return None
    return parsed

def first_failing_index(values):
    for idx, value in enumerate(values):
        if not isinstance(value, int):
            return idx
    return -1

def summarize_checks(results):
    passed = sum(1 for item in results if item)
    failed = sum(1 for item in results if not item)
    return {
        'passed': passed,
        'failed': failed,
        'all_passed': failed == 0,
    }

