class DebugReportBuilder:
    def __init__(self):
        self._error_types = ['SyntaxError', 'TypeError', 'NameError', 'IndexError', 'KeyError', 'ValueError', 'AttributeError', 'ZeroDivisionError']
        self._fixes = {
            'SyntaxError': 'Check for missing colons, unclosed brackets, or incorrect indentation.',
            'TypeError': 'Check that you are passing the right types to functions and operators.',
            'NameError': 'Check that all variable and function names are defined before use.',
            'IndexError': 'Check that your index is within the valid range of the list.',
            'KeyError': 'Check that the key exists in the dict; use .get() with a default.',
            'ValueError': 'Check that the value matches what the function expects.',
            'AttributeError': 'Check that the object has the method or property you are calling.',
            'ZeroDivisionError': 'Guard against dividing by zero before the division.',
        }

    def classify_error(self, error_text):
        for error_type in self._error_types:
            if error_type in error_text:
                return error_type
        return 'Unknown'

    def extract_line_number(self, traceback_text):
        for line in traceback_text.splitlines():
            if 'line ' in line:
                parts = line.split('line ')
                if len(parts) > 1:
                    try:
                        return int(parts[1].split(',')[0].strip())
                    except ValueError:
                        pass
        return None

    def suggest_fix(self, error_type):
        return self._fixes.get(error_type, 'Read the error message carefully and check that line in your code.')

    def format_report(self, error_text, code_line):
        return {
            'type': self.classify_error(error_text),
            'line': self.extract_line_number(error_text),
            'suggestion': self.suggest_fix(self.classify_error(error_text)),
            'code_line': code_line,
        }

    def build_debug_summary(self, reports):
        by_type = {}
        for report in reports:
            t = report['type']
            by_type[t] = by_type.get(t, 0) + 1
        most_common = max(by_type, key=by_type.get) if by_type else None
        return {'total': len(reports), 'by_type': by_type, 'most_common': most_common}
